import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.BN2sqjC1.js";const v=JSON.parse('{"title":"Vault privati e condivisi","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/vault-privati-condivisi.md","filePath":"user-guide/vault-privati-condivisi.md"}'),r={name:"user-guide/vault-privati-condivisi.md"};function s(n,e,l,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="vault-privati-e-condivisi" tabindex="-1">Vault privati e condivisi <a class="header-anchor" href="#vault-privati-e-condivisi" aria-label="Permalink to &quot;Vault privati e condivisi&quot;">​</a></h1><p>Quando collegate un vault al cloud scegliete uno di due tipi. <strong>La scelta è definitiva</strong>: non si può cambiare in seguito (per cambiare tipo si crea un nuovo vault e si spostano le note).</p><table tabindex="0"><thead><tr><th></th><th>Vault <strong>condiviso</strong></th><th>Vault <strong>privato</strong></th></tr></thead><tbody><tr><td>Cifratura end-to-end (E2EE)</td><td>No: le note sono salvate in chiaro sul server</td><td><strong>Sì</strong>: cifrate sul vostro dispositivo prima di uscire</td></tr><tr><td>Chi può leggere il contenuto</td><td>Voi, le persone con cui condividete, e chi amministra il server</td><td><strong>Solo voi</strong> (chi conosce passphrase o chiave di recupero)</td></tr><tr><td>Nomi di file e cartelle</td><td>Visibili al server</td><td>Cifrati: il server non li vede</td></tr><tr><td>Condivisione con altri</td><td>Sì, con utenti e gruppi</td><td><strong>No</strong></td></tr><tr><td>Esportazione ZIP dalla Web UI</td><td>Sì</td><td>Sì, ma decifrata <strong>nel vostro browser</strong> con passphrase o chiave</td></tr><tr><td>Se perdete l&#39;accesso</td><td>L&#39;amministratore può aiutarvi con l&#39;account</td><td><strong>I dati sono irrecuperabili</strong></td></tr></tbody></table><p>Un vault privato si crea dal desktop (collegando una cartella al cloud) oppure dalla Web UI: <em>I miei vault → Nuovo vault → Privato</em> apre il workbench del browser, dove scegliete la passphrase e salvate la chiave di recupero. Rinomina, eliminazione (ripristinabile per il periodo di conservazione) e ripristino funzionano come per i vault condivisi: vedete <a href="./sync-cloud.html#gestire-i-vault-nel-cloud">Sincronizzazione e cloud</a>.</p><h2 id="che-cosa-significa-e2ee" tabindex="-1">Che cosa significa &quot;E2EE&quot; <a class="header-anchor" href="#che-cosa-significa-e2ee" aria-label="Permalink to &quot;Che cosa significa &quot;E2EE&quot;&quot;">​</a></h2><p><em>End-to-end encryption</em>: la cifratura avviene sul vostro computer, con una chiave che il server non possiede mai. Il server conserva solo dati illeggibili e non può né leggerli né consegnarli a terzi, neppure su richiesta dell&#39;amministratore. Dettagli utili:</p><ul><li>Il contenuto è protetto da una chiave casuale a 256 bit del vault. Questa chiave è a sua volta protetta dalla vostra <strong>passphrase</strong> (trasformata con una funzione lenta, Argon2id, per rendere costoso indovinarla) e da una <strong>chiave di recupero</strong>.</li><li>La passphrase del vault è <strong>diversa dalla password dell&#39;account</strong> e <strong>non viene mai inviata</strong> al server.</li><li>Poiché il server non vede il contenuto, per i vault privati <strong>non</strong> funzionano le funzioni che richiedono di leggerlo lato server (condivisione, esportazione dal server). La ricerca e il grafo funzionano normalmente perché sono calcolati sul vostro dispositivo.</li><li>I metadati inevitabili (dimensione dei blocchi cifrati, momenti di sincronizzazione) restano visibili al server.</li></ul><h2 id="passphrase-e-chiave-di-recupero" tabindex="-1">Passphrase e chiave di recupero <a class="header-anchor" href="#passphrase-e-chiave-di-recupero" aria-label="Permalink to &quot;Passphrase e chiave di recupero&quot;">​</a></h2><p>Creando un vault privato scegliete una <strong>passphrase</strong> (almeno 12 caratteri; alcune parole casuali sono meglio di una parola con simboli). L&#39;app mostra la <strong>chiave di recupero</strong> <strong>una sola volta</strong>: copiatela, salvatela come file o stampatela e conservatela in un posto sicuro (gestore di password, cassaforte). Per confermare vi chiede di digitarla di nuovo.</p><ul><li><strong>Dimenticata la passphrase:</strong> sbloccate con la chiave di recupero; l&#39;app vi fa scegliere subito una nuova passphrase e vi propone di generare una nuova chiave di recupero (la vecchia smette di funzionare).</li><li><strong>Persa la chiave ma ricordate la passphrase:</strong> continuate a usare il vault e, appena possibile, generate una nuova chiave di recupero.</li><li><strong>Persi entrambi:</strong> <strong>nessuno può recuperare i dati</strong>, nemmeno gli amministratori. Se esiste una copia locale decifrata del vault su un dispositivo già sbloccato, copiatela subito altrove.</li><li>Su ogni nuovo dispositivo il vault si <strong>sblocca</strong> con la passphrase (o la chiave di recupero); <em>Sblocca vault cifrato</em> nella palette comandi riapre la finestra se l&#39;avete chiusa.</li></ul><h2 id="quale-scegliere" tabindex="-1">Quale scegliere? <a class="header-anchor" href="#quale-scegliere" aria-label="Permalink to &quot;Quale scegliere?&quot;">​</a></h2><p>Scegliete <strong>privato</strong> per diari, dati personali o sensibili e quando non serve condividere. Scegliete <strong>condiviso</strong> quando volete collaborare con colleghi o gruppi, o quando l&#39;organizzazione vuole poter assistere nel recupero. Se avete dubbi: un vault privato è più sicuro, ma la sicurezza ha il prezzo dell&#39;irrecuperabilità.</p>',12)])])}const g=i(r,[["render",s]]);export{v as __pageData,g as default};
